fun @bubblesort(%arr_param: *i32): i32 {
%0:
  @arr = alloc *i32
  store %arr_param, @arr
  @i = alloc i32
  @j = alloc i32
  store 0, @i
  jump %bb0_while_start

%bb0_while_start:
  %1 = load @i
  %2 = load @n
  %3 = sub %2, 1
  %4 = lt %1, %3
  br %4, %bb1_while_body, %bb2_while_end

%bb1_while_body:
  store 0, @j
  jump %bb3_while_start

%bb2_while_end:
  ret 0

%bb3_while_start:
  %5 = load @j
  %6 = load @n
  %7 = load @i
  %8 = sub %6, %7
  %9 = sub %8, 1
  %10 = lt %5, %9
  br %10, %bb4_while_body, %bb5_while_end

%bb4_while_body:
