590	    let is_inst = data.kind().is_global_alloc();
591	    let value = self.program.new_value_data(data);
592	    if is_inst {
593	      self.program.inst_layout.push(value);
594	    }
595	    value
596	  }
597	}
598	
599	impl<'a> ValueBuilder for GlobalBuilder<'a> {}
600	impl<'a> GlobalInstBuilder for GlobalBuilder<'a> {}

