 40	impl Program {
 41	  /// Creates a new program.
 42	  pub fn new() -> Self {
 43	    Self::default()
 44	  }
 45	
 46	  /// Creates a new global value in the current program.
 47	  /// Returns a [`GlobalBuilder`] for building the new global value.
 48	  pub fn new_value(&mut self) -> GlobalBuilder {
 49	    GlobalBuilder { program: self }
 50	  }
 51	
 52	  /// Creates a new global value by its value data. Returns the handle of
 53	  /// the created value. This method will be called by [`GlobalBuilder`].
 54	  ///
 55	  /// # Panics
 56	  ///
 57	  /// Panics if the given value data uses unexisted values.
 58	  pub(in crate::ir) fn new_value_data(&mut self, data: ValueData) -> Value {
 59	    let value = Value(next_global_value_id());
 60	    for v in data.kind().value_uses() {
 61	      data_mut!(self, v).used_by.insert(value);
 62	    }
 63	    self.values.borrow_mut().insert(value, data);
 64	    value
 65	  }
 66	
 67	  /// Removes the given global value by its handle. Returns the
 68	  /// corresponding value data.
 69	  ///
 70	  /// # Panics
 71	  ///
 72	  /// Panics if the given value does not exist, or the removed value is
 73	  /// currently used by other values.
 74	  pub fn remove_value(&mut self, value: Value) -> ValueData {
 75	    let data = self
 76	      .values
 77	      .borrow_mut()
 78	      .remove(&value)
 79	      .expect("`value` does not exist");
 80	    if data.kind().is_global_alloc() {
 81	      self
 82	        .inst_layout
 83	        .remove(self.inst_layout.iter().position(|v| *v == value).unwrap());
 84	    }
 85	    assert!(data.used_by.is_empty(), "`value` is used by other values");
 86	    for v in data.kind().value_uses() {
 87	      data_mut!(self, v).used_by.remove(&value);
 88	    }
 89	    data
 90	  }
 91	
 92	  /// Sets the name of the given global value.
 93	  ///
 94	  /// # Panics
 95	  ///
 96	  /// Panics if the given value does not exist,
 97	  /// or the given name (if exists) not starts with `%` or `@`.
 98	  pub fn set_value_name(&mut self, value: Value, name: Option<String>) {
 99	    self
100	      .values
101	      .borrow_mut()
102	      .get_mut(&value)
103	      .expect("`value` does not exist")
104	      .set_name(name);
105	  }
