128	  /// Creates a new function in the current program.
129	  pub fn new_func(&mut self, mut data: FunctionData) -> Function {
130	    let func = Function(next_func_id());
131	    data.dfg.globals = Rc::downgrade(&self.values);
132	    data.dfg.func_tys = Rc::downgrade(&self.func_tys);
133	    self.func_tys.borrow_mut().insert(func, data.ty.clone());
134	    self.funcs.insert(func, data);
135	    self.func_layout.push(func);
136	    func
137	  }
138	
139	  /// Removes the given function by its handle.
140	  ///
141	  /// Returns the function data if the function was previously in the program.
142	  pub fn remove_func(&mut self, func: Function) -> Option<FunctionData> {
143	    self.func_tys.borrow_mut().remove(&func);
144	    self
145	      .func_layout
146	      .remove(self.func_layout.iter().position(|f| *f == func).unwrap());
147	    self.funcs.remove(&func)
148	  }
