202	/// Data of Koopa IR function.
203	///
204	/// Functions can hold basic blocks.
205	pub struct FunctionData {
206	  ty: Type,
207	  name: String,
208	  params: Vec<Value>,
209	  dfg: DataFlowGraph,
210	  layout: Layout,
211	}
212	
213	impl FunctionData {
214	  /// Creates a new function definition.
215	  ///
216	  /// # Panics
217	  ///
218	  /// Panics if the given name not starts with `%` or `@`, or the given
219	  /// type can not construct a valid function type.
220	  pub fn new(name: String, params_ty: Vec<Type>, ret_ty: Type) -> Self {
221	    use crate::ir::values::FuncArgRef;
222	    Self::check_sanity(&name, params_ty.iter());
223	    // create function argument references
224	    let mut dfg = DataFlowGraph::new();
225	    let params = params_ty
226	      .iter()
227	      .enumerate()
228	      .map(|(i, ty)| dfg.new_value_data(FuncArgRef::new_data(i, ty.clone())))
229	      .collect();
230	    Self {
231	      ty: Type::get_function(params_ty, ret_ty),
232	      name,
233	      params,
234	      dfg,
235	      layout: Layout::new(),
236	    }
237	  }
238	
239	  /// Creates a new function definition with parameter names.
240	  ///
241	  /// # Panics
242	  ///
243	  /// Panics if the given name not starts with `%` or `@`, or the given
244	  /// type can not construct a valid function type.
245	  pub fn with_param_names(name: String, params: Vec<(Option<String>, Type)>, ret_ty: Type) -> Self {
246	    use crate::ir::values::FuncArgRef;
247	    Self::check_sanity(&name, params.iter().map(|(_, ty)| ty));
248	    // create function argument references
249	    let mut dfg = DataFlowGraph::new();
250	    let (params, params_ty) = params
251	      .into_iter()
252	      .enumerate()
253	      .map(|(i, (n, ty))| {
254	        let v = dfg.new_value_data(FuncArgRef::new_data(i, ty.clone()));
255	        dfg.set_value_name(v, n);
256	        (v, ty)
257	      })
258	      .unzip();
259	    Self {
260	      ty: Type::get_function(params_ty, ret_ty),
261	      name,
262	      params,
263	      dfg,
264	      layout: Layout::new(),
265	    }
266	  }
267	
268	  /// Creates a new function declaration.
269	  ///
270	  /// # Panics
271	  ///
272	  /// Panics if the given name not starts with `%` or `@`, or the given
273	  /// type can not construct a valid function type.
274	  pub fn new_decl(name: String, params_ty: Vec<Type>, ret_ty: Type) -> Self {
275	    Self::check_sanity(&name, params_ty.iter());
276	    Self {
277	      ty: Type::get_function(params_ty, ret_ty),
278	      name,
279	      params: Vec::new(),
280	      dfg: DataFlowGraph::new(),
281	      layout: Layout::new(),
282	    }
283	  }
284	
285	  /// Checks if the given name and type is valid.
286	  ///
287	  /// # Panics
288	  ///
289	  /// Panics if the given name and type is invalid.
290	  fn check_sanity<'a, T>(name: &str, mut params: T)
291	  where
292	    T: Iterator<Item = &'a Type>,
293	  {
294	    assert!(
295	      name.len() > 1 && (name.starts_with('%') || name.starts_with('@')),
296	      "invalid function name"
297	    );
298	    assert!(
299	      params.all(|p| !p.is_unit()),
300	      "parameter type must not be `unit`!"
301	    );
302	  }
303	
304	  /// Returns a reference to the function's type.
305	  pub fn ty(&self) -> &Type {
306	    &self.ty
307	  }
308	
309	  /// Returns a reference to the function's name.
310	  pub fn name(&self) -> &str {
311	    &self.name
312	  }
313	
314	  /// Sets the function's name.
315	  pub fn set_name(&mut self, name: String) {
316	    self.name = name;
317	  }
318	
319	  /// Returns a reference to the function parameters.
320	  pub fn params(&self) -> &[Value] {
321	    &self.params
322	  }
323	
324	  /// Returns a reference to the data flow graph.
325	  pub fn dfg(&self) -> &DataFlowGraph {
326	    &self.dfg
327	  }
328	
329	  /// Returns a mutable reference to the data flow graph.
330	  pub fn dfg_mut(&mut self) -> &mut DataFlowGraph {
331	    &mut self.dfg
332	  }
333	
334	  /// Returns a reference to the layout.
335	  pub fn layout(&self) -> &Layout {
336	    &self.layout
337	  }
338	
339	  /// Returns a mutable reference to the layout.
340	  pub fn layout_mut(&mut self) -> &mut Layout {
341	    &mut self.layout
342	  }
343	}
