666	    self.index += 1;
667	    match self.kind {
668	      ValueKind::Branch(br) => match cur {
669	        0 => Some(br.true_bb()),
670	        1 => Some(br.false_bb()),
671	        _ => None,
672	      },
673	      ValueKind::Jump(jump) => match cur {
674	        0 => Some(jump.target()),
675	        _ => None,
676	      },
677	      _ => None,
678	    }
679	  }
680	}

