     1	//! Types of Koopa IR values.
     2	//!
     3	//! Each Koopa IR value and function should have a type. A type can be
     4	//! a 32-bit integer type, a unit type, an array type, a pointer type,
     5	//! or a function type.
     6	
     7	use std::cell::{Cell, RefCell};
     8	use std::collections::HashMap;
     9	use std::rc::Rc;
    10	use std::{cmp, fmt, hash, mem};
    11	
    12	/// Kind of type.
    13	#[derive(Hash, Clone, PartialEq, Eq)]
    14	pub enum TypeKind {
    15	  /// 32-bit integer.
    16	  Int32,
    17	  /// Unit (void).
    18	  Unit,
    19	  /// Array (with base type and length).
    20	  Array(Type, usize),
    21	  /// Pointer (with base type).
    22	  Pointer(Type),
    23	  /// Function (with parameter types and return type).
    24	  Function(Vec<Type>, Type),
    25	}
    26	
    27	impl fmt::Display for TypeKind {
    28	  fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
    29	    match self {
    30	      TypeKind::Int32 => write!(f, "i32"),
    31	      TypeKind::Unit => write!(f, "unit"),
    32	      TypeKind::Array(t, len) => write!(f, "[{}, {}]", t, len),
    33	      TypeKind::Pointer(t) => write!(f, "*{}", t),
    34	      TypeKind::Function(params, ret) => {
    35	        write!(f, "(")?;
    36	        let mut first = true;
    37	        for param in params {
    38	          if !first {
    39	            write!(f, ", ")?;
    40	          }
    41	          write!(f, "{}", param)?;
    42	          first = false;
    43	        }
    44	        if !ret.is_unit() {
    45	          write!(f, "): {}", ret)
    46	        } else {
    47	          write!(f, ")")
    48	        }
    49	      }
    50	    }
    51	  }
    52	}
    53	
    54	/// Types of Koopa IR values.
    55	#[derive(Clone, Eq)]
    56	pub struct Type(Rc<TypeKind>);
    57	
    58	impl Type {
    59	  thread_local! {
    60	    /// Pool of all created types.
    61	    static POOL: RefCell<HashMap<TypeKind, Type>> = RefCell::new(HashMap::new());
    62	
    63	    /// Size of pointers.
    64	    static PTR_SIZE: Cell<usize> = Cell::new(mem::size_of::<*const ()>());
    65	  }
    66	
    67	  /// Returns a type by the given [`TypeKind`].
    68	  pub fn get(type_data: TypeKind) -> Type {
    69	    Self::POOL.with(|pool| {
    70	      let mut pool = pool.borrow_mut();
    71	      pool.get(&type_data).cloned().unwrap_or_else(|| {
    72	        let v = Self(Rc::new(type_data.clone()));
    73	        pool.insert(type_data, v.clone());
    74	        v
    75	      })
    76	    })
    77	  }
    78	
    79	  /// Returns an `i32` type.
    80	  pub fn get_i32() -> Type {
    81	    Type::get(TypeKind::Int32)
    82	  }
    83	
    84	  /// Returns an `unit` type.
    85	  pub fn get_unit() -> Type {
    86	    Type::get(TypeKind::Unit)
    87	  }
    88	
    89	  /// Returns an array type.
    90	  pub fn get_array(base: Type, len: usize) -> Type {
    91	    assert!(len != 0, "`len` can not be zero!");
    92	    Type::get(TypeKind::Array(base, len))
    93	  }
    94	
    95	  /// Returns an pointer type.
    96	  pub fn get_pointer(base: Type) -> Type {
    97	    Type::get(TypeKind::Pointer(base))
    98	  }
    99	
   100	  /// Returns an function type.
   101	  pub fn get_function(params: Vec<Type>, ret: Type) -> Type {
   102	    Type::get(TypeKind::Function(params, ret))
   103	  }
   104	
   105	  /// Sets the size of pointers.
   106	  pub fn set_ptr_size(size: usize) {
   107	    Self::PTR_SIZE.with(|ptr_size| ptr_size.set(size));
   108	  }
   109	
   110	  /// Returns a reference to the kind of the current type.
   111	  pub fn kind(&self) -> &TypeKind {
   112	    &self.0
   113	  }
   114	
   115	  /// Checks if the current type is an integer type.
   116	  pub fn is_i32(&self) -> bool {
   117	    matches!(self.0.as_ref(), TypeKind::Int32)
   118	  }
   119	
   120	  /// Checks if the current type is a unit type.
   121	  pub fn is_unit(&self) -> bool {
   122	    matches!(self.0.as_ref(), TypeKind::Unit)
   123	  }
   124	
   125	  /// Returns the size of the current type in bytes.
   126	  pub fn size(&self) -> usize {
   127	    match self.kind() {
   128	      TypeKind::Int32 => 4,
   129	      TypeKind::Unit => 0,
   130	      TypeKind::Array(ty, len) => ty.size() * len,
   131	      TypeKind::Pointer(..) | TypeKind::Function(..) => Self::PTR_SIZE.with(|s| s.get()),
   132	    }
   133	  }
   134	}
   135	
   136	impl cmp::PartialEq for Type {
   137	  fn eq(&self, other: &Self) -> bool {
   138	    Rc::ptr_eq(&self.0, &other.0)
   139	  }
   140	}
   141	
   142	impl fmt::Display for Type {
   143	  fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
   144	    write!(f, "{}", self.0)
   145	  }
   146	}
   147	
   148	impl fmt::Debug for Type {
   149	  fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
   150	    write!(f, "{}", self.0)
   151	  }
   152	}
   153	
   154	impl hash::Hash for Type {
   155	  fn hash<H: hash::Hasher>(&self, state: &mut H) {
   156	    self.0.hash(state);
   157	  }
   158	}
   159	
   160	#[cfg(test)]
   161	mod test {
   162	  use super::*;
   163	
   164	  #[test]
   165	  fn print_type() {
   166	    assert_eq!(format!("{}", Type::get_i32()), "i32");
   167	    assert_eq!(format!("{}", Type::get_unit()), "unit");
   168	    assert_eq!(
   169	      format!("{}", Type::get_array(Type::get_i32(), 10)),
   170	      "[i32, 10]"
   171	    );
   172	    assert_eq!(
   173	      format!(
   174	        "{}",
   175	        Type::get_array(Type::get_array(Type::get_i32(), 2), 3)
   176	      ),
   177	      "[[i32, 2], 3]"
   178	    );
   179	    assert_eq!(
   180	      format!("{}", Type::get_pointer(Type::get_pointer(Type::get_i32()))),
   181	      "**i32"
   182	    );
   183	    assert_eq!(
   184	      format!("{}", Type::get_function(Vec::new(), Type::get_unit())),
   185	      "()"
   186	    );
   187	    assert_eq!(
   188	      format!(
   189	        "{}",
   190	        Type::get_function(vec![Type::get_i32()], Type::get_unit())
   191	      ),
   192	      "(i32)"
   193	    );
   194	    assert_eq!(
   195	      format!(
   196	        "{}",
   197	        Type::get_function(vec![Type::get_i32(), Type::get_i32()], Type::get_i32())
   198	      ),
   199	      "(i32, i32): i32"
   200	    );
   201	  }
   202	
   203	  #[test]
   204	  fn type_eq() {
   205	    assert_eq!(Type::get_i32(), Type::get_i32());
   206	    assert_eq!(
   207	      Type::get_array(Type::get_i32(), 6),
   208	      Type::get_array(Type::get_i32(), 6)
   209	    );
   210	    assert_ne!(
   211	      Type::get_array(Type::get_i32(), 6),
   212	      Type::get_array(Type::get_i32(), 7)
   213	    );
   214	  }
   215	
   216	  #[test]
   217	  fn type_size() {
   218	    assert_eq!(Type::get_i32().size(), 4);
   219	    assert_eq!(Type::get_unit().size(), 0);
   220	    assert_eq!(Type::get_array(Type::get_i32(), 5).size(), 4 * 5);
   221	    assert_eq!(
   222	      Type::get_array(Type::get_array(Type::get_i32(), 6), 5).size(),
   223	      4 * 6 * 5
   224	    );
   225	    assert_eq!(
   226	      Type::get_pointer(Type::get_array(Type::get_i32(), 5)).size(),
   227	      mem::size_of::<usize>()
   228	    );
   229	    assert_eq!(
   230	      Type::get_array(Type::get_pointer(Type::get_i32()), 5).size(),
   231	      mem::size_of::<usize>() * 5
   232	    );
   233	    assert_eq!(
   234	      Type::get_function(vec![Type::get_i32(), Type::get_i32()], Type::get_unit()).size(),
   235	      mem::size_of::<usize>()
   236	    );
   237	    Type::set_ptr_size(4);
   238	    assert_eq!(
   239	      Type::get_array(Type::get_pointer(Type::get_i32()), 5).size(),
   240	      4 * 5
   241	    );
   242	  }
   243	}
