     1	//! Data flow graph ([`DataFlowGraph`]) related implementations.
     2	
     3	use crate::ir::builder::{BlockBuilder, LocalBuilder, ReplaceBuilder};
     4	use crate::ir::entities::{BasicBlock, BasicBlockData, Value, ValueData};
     5	use crate::ir::entities::{FuncTypeMapCell, GlobalValueMapCell};
     6	use crate::ir::idman::{next_bb_id, next_local_value_id};
     7	use std::collections::HashMap;
     8	
     9	/// Data flow graph of a function.
    10	///
    11	/// `DataFlowGraph` holds all data of values ([`ValueData`]) and basic
    12	/// blocks ([`BasicBlockData`]), and maintains their use-define and
    13	/// define-use chain.
    14	pub struct DataFlowGraph {
    15	  pub(in crate::ir) globals: GlobalValueMapCell,
    16	  pub(in crate::ir) func_tys: FuncTypeMapCell,
    17	  values: HashMap<Value, ValueData>,
    18	  bbs: HashMap<BasicBlock, BasicBlockData>,
    19	}
    20	
    21	/// Returns a reference to the value data by the given value handle.
    22	macro_rules! data {
    23	  ($self:ident, $value:expr) => {
    24	    $self
    25	      .globals
    26	      .upgrade()
    27	      .unwrap()
    28	      .borrow()
    29	      .get(&$value)
    30	      .or_else(|| $self.values.get(&$value))
    31	      .expect("value does not exist")
    32	  };
    33	}
    34	
    35	/// Returns a mutable reference to the value data by the given value handle.
    36	macro_rules! data_mut {
    37	  ($self:ident, $value:expr) => {
    38	    $self
    39	      .globals
    40	      .upgrade()
    41	      .unwrap()
    42	      .borrow_mut()
    43	      .get_mut(&$value)
    44	      .or_else(|| $self.values.get_mut(&$value))
    45	      .expect("value does not exist")
    46	  };
    47	}
    48	
    49	impl DataFlowGraph {
    50	  /// Creates a new data flow graph.
    51	  pub(in crate::ir) fn new() -> Self {
    52	    Self {
    53	      globals: GlobalValueMapCell::new(),
    54	      func_tys: FuncTypeMapCell::new(),
    55	      values: HashMap::new(),
    56	      bbs: HashMap::new(),
    57	    }
    58	  }
    59	
    60	  /// Creates a new value in the current data flow graph.
    61	  /// Returns a [`LocalBuilder`] for building the new local value.
    62	  pub fn new_value(&mut self) -> LocalBuilder {
    63	    LocalBuilder { dfg: self }
    64	  }
    65	
    66	  /// Creates a new local value by its value data. Returns the handle of
    67	  /// the created value. This method will be called by [`LocalBuilder`].
    68	  ///
    69	  /// # Panics
    70	  ///
    71	  /// Panics if the given value data uses unexisted values or basic blocks.
    72	  pub(in crate::ir) fn new_value_data(&mut self, data: ValueData) -> Value {
    73	    let value = Value(next_local_value_id());
    74	    for v in data.kind().value_uses() {
    75	      data_mut!(self, v).used_by.insert(value);
    76	    }
    77	    for bb in data.kind().bb_uses() {
    78	      self.bb_mut(bb).used_by.insert(value);
    79	    }
    80	    self.values.insert(value, data);
    81	    value
    82	  }
    83	
    84	  /// Replaces the given value with a new value.
    85	  /// Returns a [`ReplaceBuilder`] for building the new value.
    86	  ///
    87	  /// # Panics
    88	  ///
    89	  /// Panics if the given value does not exist.
    90	  pub fn replace_value_with(&mut self, value: Value) -> ReplaceBuilder {
    91	    ReplaceBuilder { dfg: self, value }
    92	  }
    93	
    94	  /// Replaces the given value with a new value data.
    95	  /// This method will be called by [`ReplaceBuilder`].
    96	  ///
    97	  /// # Panics
    98	  ///
    99	  /// Panics if the given value does not exist.
   100	  pub(in crate::ir) fn replace_value_with_data(&mut self, value: Value, data: ValueData) {
   101	    let old = self.values.remove(&value).unwrap();
   102	    for v in old.kind().value_uses() {
   103	      data_mut!(self, v).used_by.remove(&value);
   104	    }
   105	    for bb in old.kind().bb_uses() {
   106	      self.bb_mut(bb).used_by.remove(&value);
   107	    }
   108	    for v in data.kind().value_uses() {
   109	      data_mut!(self, v).used_by.insert(value);
   110	    }
   111	    for bb in data.kind().bb_uses() {
   112	      self.bb_mut(bb).used_by.insert(value);
   113	    }
   114	    self.values.insert(value, data);
   115	  }
   116	
   117	  /// Removes the given value. Returns the corresponding value data.
   118	  ///
   119	  /// # Panics
   120	  ///
   121	  /// Panics if the given value does not exist, or the removed value is
   122	  /// currently used by other values.
   123	  pub fn remove_value(&mut self, value: Value) -> ValueData {
   124	    let data = self.values.remove(&value).expect("`value` does not exist");
   125	    assert!(data.used_by.is_empty(), "`value` is used by other values");
   126	    for v in data.kind().value_uses() {
   127	      data_mut!(self, v).used_by.remove(&value);
   128	    }
   129	    for bb in data.kind().bb_uses() {
   130	      self.bb_mut(bb).used_by.remove(&value);
   131	    }
   132	    data
   133	  }
   134	
   135	  /// Sets the name of the given value.
   136	  ///
   137	  /// # Panics
   138	  ///
   139	  /// Panics if the given value does not exist,
   140	  /// or the given name (if exists) not starts with `%` or `@`.
   141	  pub fn set_value_name(&mut self, value: Value, name: Option<String>) {
   142	    self
   143	      .values
   144	      .get_mut(&value)
   145	      .expect("`value` does not exist")
   146	      .set_name(name);
   147	  }
   148	
   149	  /// Returns a reference to the given local value.
   150	  ///
   151	  /// # Panics
   152	  ///
   153	  /// Panics if the given local value does not exist.
   154	  pub fn value(&self, value: Value) -> &ValueData {
   155	    self.values.get(&value).expect("`value` does not exist")
   156	  }
   157	
   158	  /// Returns a reference to the value map.
   159	  pub fn values(&self) -> &HashMap<Value, ValueData> {
   160	    &self.values
   161	  }
   162	
   163	  /// Checks if the two given values are equal.
   164	  pub fn value_eq(&self, lhs: Value, rhs: Value) -> bool {
   165	    self.data_eq(data!(self, lhs), data!(self, rhs))
   166	  }
   167	
   168	  /// Checks if the two given value data are equal.
   169	  pub fn data_eq(&self, lhs: &ValueData, rhs: &ValueData) -> bool {
   170	    use crate::ir::entities::ValueKind::*;
   171	    macro_rules! return_if {
   172	      ($e:expr) => {
   173	        if $e {
   174	          return false;
   175	        }
   176	      };
   177	    }
   178	    return_if!(lhs.ty() != rhs.ty());
   179	    match (lhs.kind(), rhs.kind()) {
   180	      (Integer(l), Integer(r)) => return_if!(l.value() != r.value()),
   181	      (ZeroInit(_), ZeroInit(_)) => return true,
   182	      (Undef(_), Undef(_)) => return true,
   183	      (Aggregate(l), Aggregate(r)) => return_if!(l.elems().len() != r.elems().len()),
   184	      (FuncArgRef(l), FuncArgRef(r)) => return_if!(l.index() != r.index()),
   185	      (BlockArgRef(l), BlockArgRef(r)) => return_if!(l.index() != r.index()),
   186	      (Alloc(_), Alloc(_)) => return true,
   187	      (GlobalAlloc(_), GlobalAlloc(_)) => (),
   188	      (Load(_), Load(_)) => (),
   189	      (Store(_), Store(_)) => (),
   190	      (GetPtr(_), GetPtr(_)) => (),
   191	      (GetElemPtr(_), GetElemPtr(_)) => (),
   192	      (Binary(l), Binary(r)) => return_if!(l.op() != r.op()),
   193	      (Branch(l), Branch(r)) => {
   194	        return_if!(
   195	          l.true_bb() != r.true_bb()
   196	            || l.false_bb() != r.false_bb()
   197	            || l.true_args().len() != r.true_args().len()
   198	            || l.false_args().len() != r.false_args().len()
   199	        )
   200	      }
   201	      (Jump(l), Jump(r)) => {
   202	        return_if!(l.target() != r.target() || l.args().len() != r.args().len())
   203	      }
   204	      (Call(l), Call(r)) => {
   205	        return_if!(l.callee() != r.callee() || l.args().len() != r.args().len())
   206	      }
   207	      (Return(l), Return(r)) => return_if!(l.value().xor(r.value()).is_some()),
   208	      _ => return false,
   209	    }
   210	    for (lu, ru) in lhs.kind().value_uses().zip(rhs.kind().value_uses()) {
   211	      return_if!(!self.value_eq(lu, ru));
   212	    }
   213	    true
   214	  }
   215	
   216	  /// Creates a new basic block in the current data flow graph.
   217	  /// Returns a [`BlockBuilder`] for building the new basic block.
   218	  pub fn new_bb(&mut self) -> BlockBuilder {
   219	    BlockBuilder { dfg: self }
   220	  }
   221	
   222	  /// Creates a new basic block in the current data flow graph.
   223	  /// Returns the handle of the created basic block.
   224	  pub(in crate::ir) fn new_bb_data(&mut self, data: BasicBlockData) -> BasicBlock {
   225	    let bb = BasicBlock(next_bb_id());
   226	    self.bbs.insert(bb, data);
   227	    bb
   228	  }
   229	
   230	  /// Removes the given basic block, also removes all basic block
   231	  /// parameters. Returns the corresponding basic block data.
   232	  ///
   233	  /// # Panics
   234	  ///
   235	  /// Panics if:
   236	  ///
   237	  /// * the given basic block does not exist, or
   238	  /// * the removed basic block is currently used by other values, or
   239	  /// * the parameters of the removed basic block do not exist, or
   240	  ///   are currently used by other values.
   241	  pub fn remove_bb(&mut self, bb: BasicBlock) -> BasicBlockData {
   242	    let data = self.bbs.remove(&bb).expect("`bb` does not exist");
   243	    assert!(data.used_by.is_empty(), "`bb` is used by other values");
   244	    for p in data.params() {
   245	      let param = self
   246	        .values
   247	        .remove(p)
   248	        .expect("basic block parameter does not exist");
   249	      assert!(
   250	        param.used_by.is_empty(),
   251	        "basic block parameter is used by other values"
   252	      );
   253	    }
   254	    data
   255	  }
   256	
   257	  /// Returns a reference to the given basic block.
   258	  ///
   259	  /// # Panics
   260	  ///
   261	  /// Panics if the given basic block does not exist.
   262	  pub fn bb(&self, bb: BasicBlock) -> &BasicBlockData {
   263	    self.bbs.get(&bb).expect("`bb` does not exist")
   264	  }
   265	
   266	  /// Returns a mutable reference to the given basic block.
   267	  ///
   268	  /// # Panics
   269	  ///
   270	  /// Panics if the given basic block does not exist.
   271	  pub fn bb_mut(&mut self, bb: BasicBlock) -> &mut BasicBlockData {
   272	    self.bbs.get_mut(&bb).expect("`bb` does not exist")
   273	  }
   274	
   275	  /// Returns a reference to the basic block map.
   276	  pub fn bbs(&self) -> &HashMap<BasicBlock, BasicBlockData> {
   277	    &self.bbs
   278	  }
   279	
   280	  /// Returns a mutable reference to the basic block map.
   281	  pub fn bbs_mut(&mut self) -> &mut HashMap<BasicBlock, BasicBlockData> {
   282	    &mut self.bbs
   283	  }
   284	}
