   286	#[cfg(test)]
   287	mod test {
   288	  use crate::ir::builder_traits::*;
   289	  use crate::ir::{BinaryOp, FunctionData, Program, Type};
   290	
   291	  #[test]
   292	  fn value_eq() {
   293	    let mut program = Program::new();
   294	    let func = program.new_func(FunctionData::new("@test".into(), vec![], Type::get_unit()));
   295	    let func = program.func_mut(func);
   296	    // 10 == 10
   297	    let int1 = func.dfg_mut().new_value().integer(10);
   298	    let int2 = func.dfg_mut().new_value().integer(10);
   299	    assert!(func.dfg().value_eq(int1, int2));
   300	    // 10 + 10 - 10 == 10 + 10 - 10
   301	    let add1 = func.dfg_mut().new_value().binary(BinaryOp::Add, int1, int1);
   302	    let sub1 = func.dfg_mut().new_value().binary(BinaryOp::Sub, add1, int1);
   303	    let add2 = func.dfg_mut().new_value().binary(BinaryOp::Add, int2, int2);
   304	    let sub2 = func.dfg_mut().new_value().binary(BinaryOp::Sub, add2, int2);
   305	    assert!(func.dfg().value_eq(sub1, sub2));
   306	    // 10 != 9
   307	    let int1 = func.dfg_mut().new_value().integer(10);
   308	    let int2 = func.dfg_mut().new_value().integer(9);
   309	    assert!(!func.dfg().value_eq(int1, int2));
   310	    // 10 + 10 - 10 != 10 + 9 - 9 (lexical)
   311	    let add1 = func.dfg_mut().new_value().binary(BinaryOp::Add, int1, int1);
   312	    let sub1 = func.dfg_mut().new_value().binary(BinaryOp::Sub, add1, int1);
   313	    let add2 = func.dfg_mut().new_value().binary(BinaryOp::Add, int1, int2);
   314	    let sub2 = func.dfg_mut().new_value().binary(BinaryOp::Sub, add2, int2);
   315	    assert!(!func.dfg().value_eq(sub1, sub2));
