   100	  pub(in crate::ir) fn replace_value_with_data(&mut self, value: Value, data: ValueData) {
   101	    let old = self.values.remove(&value).unwrap();
   102	    for v in old.kind().value_uses() {
   103	      data_mut!(self, v).used_by.remove(&value);
   104	    }
   105	    for bb in old.kind().bb_uses() {
   106	      self.bb_mut(bb).used_by.remove(&value);
   107	    }
   108	    for v in data.kind().value_uses() {
   109	      data_mut!(self, v).used_by.insert(value);
   110	    }
   111	    for bb in data.kind().bb_uses() {
   112	      self.bb_mut(bb).used_by.insert(value);
   113	    }
